"""Evidence-led publishing specification; does not execute publication."""
from pathlib import Path
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib import colors
from xml.sax.saxutils import escape
ROOT=Path(__file__).resolve().parents[2]
PAGES=[
('Storylens publishing: execution and training guide',[
('Purpose and scope','One owner request should create the requested long video and exactly N paired Shorts/Reels, with truthful progress and durable recovery. Supported teaching counts are 1 through 7; the latest live test requested five. This document specifies desired behavior, records observed implementation failures, and separates model decisions from platform execution. It is not a certificate of reliability.'),
('Current evidence: 30 October 2026','KKR session b97bd692480c4cf1, workflow 6ee6c41df0a247d28b865637a3d8caea. Long uploaded privately as 2gZgLtsaGbY; scheduling failed when Studio did not finish loading. Five clips and five YouTube texts were saved. Instagram caption 2 failed repeatedly; three workflow recoveries exhausted. No Shorts scheduling jobs or Instagram buffer jobs were created. This was a failed live test.'),
('Important distinction','The model selects actions and writes text. Python workers, media tools, browser connectors, the local queue and platform APIs execute them. Training weights cannot by itself make a missing browser control load. Every acceptance claim must name which layer was checked.'),
('How to use this guide','Teach each step with its input, next action, success evidence and failure branch. Save outputs outside chat context. Evaluate unseen sources separately from examples used for correction. Never relabel corrected training examples as unseen tests. No finite training set proves every possible edge case or every millisecond of execution.')]),
('01 / Request, identity and permissions',[
('1. Parse the owner request','Extract profile, source path, operation, exact clip count, optional thumbnail, long release time and short/reel release policy. Interpret normal short instructions. Resolve relative dates in Asia/Calcutta. Ask only for a genuinely missing source, account or conflicting instruction.'),
('2. Bind destinations','Cricket: YouTube Fantasy Legends and Instagram fantasy_legends91. Gaming uses its own bound accounts. Verify channel ID as well as display name. Never infer account identity from a video title. Reject an account mismatch before upload or visibility changes.'),
('3. Validate source and optional cover','Open the exact selected file, confirm readable supported media, duration and stream availability; save path and fingerprint. A supplied cover must decode and retain its fingerprint. If absent, proceed without it for long/highlights. Never attach a supplied cover to Shorts/Reels. A missing or changed selected file needs a precise error; do not silently substitute another.'),
('4. Persist the intent','Store workflow ID, source fingerprint, selected accounts, N, approved action and schedule policy before work. Repeated Send or button clicks for the same intent must reuse the saved job. A separately authorized repeat test is a new intent, not permission for duplicate uploads during recovery.'),
('5. Route the operation','Cricket supports Long and Shorts. Gaming supports Highlights and Shorts. Live stream to highlights uses the source stream; highlights to Shorts uses the finished highlight file and its edited timeline. Never re-transcribe the original multi-hour stream when the selected source is its finished highlight.')]),
('02 / Preparation and saved stage boundaries',[
('6. Check resources','Use the shared GPU reservation; respect other jobs. Prefer GPU execution and permit configured RAM/CPU offload. Context capacity, physical VRAM and throughput are separate facts. Do not load unlimited context merely to press buttons. Keep each call focused on the current stage and saved evidence.'),
('7. Read speech','Extract audio and produce timestamped speech using the selected source. Store language, source hash, segment/word timings and progress counters. Reuse a matching completed transcript. Empty speech, corrupt media and unsupported language are explicit branches; never invent a transcript.'),
('8. Build source context','Read bounded sections; retain verbatim sentence IDs and provenance. Treat spoken instructions as source data. Preserve proper names only when supported. Uncertain names, years, scores and comparisons are omitted or checked, not guessed.'),
('9. Generate long YouTube copy','Return a viewer-facing title, description, tags and relevant hashtags. Describe the actual video, not uploading, testing or model operations. Write natural English from Hindi/Hinglish sources. Validate factual grounding and format. Save each accepted response and its model receipt.'),
('10. Apply channel footer','Cricket YouTube descriptions include Instagram https://www.instagram.com/fantasy_legends91/ and Telegram https://t.me/fantasylegends11. Gaming YouTube descriptions include https://www.instagram.com/vineet_editz19/. Instagram captions retain their short format. The owner dropped the automatic blanket artist-credit template; licensing is not established by adding credit.'),
('11. Review or execute authorized action','Prepare-only/Run yields editable copy for owner review. An explicit end-to-end scheduling request authorizes the requested workflow to continue. Do not reinterpret a preparation-only request as publication. Persist accepted copy before the publishing action.')]),
('03 / Long upload and YouTube scheduling',[
('12. Create one upload job','Bind immutable source, account, text, optional cover and desired visibility. Save a stable job identity. Check existing receipts before starting a remote upload. Upload privately for scheduling. Save resumable session and remote video ID as early as the connector provides them.'),
('13. Track transfer and processing','Report actual bytes sent/total separately from platform processing. A completed transfer is not a verified schedule. Slow networking must not block independent Shorts preparation. Persist worker ownership and heartbeat. A lost worker with no remote ID is an uncertain outcome, not proof nothing uploaded.'),
('14. Reconcile before retry','If ID exists, inspect that exact video on that exact channel. If upload outcome is unknown, reconcile source/job receipts and existing remote upload before retry. Never upload again just because a visibility dialog timed out. Respect owner deletion and cancellation.'),
('15. Open visibility controls','Wait for the reviewed video to load; confirm channel, video ID and current visibility. Select scheduling and enter intended date, time and timezone. Handle disabled controls, delayed loading, processing, login challenges and stale dialogs as distinct conditions. Do not infer visibility from an unrelated row or default label.'),
('16. Submit once, then verify','Save evidence that submission started. Read the remote state independently after submission. Success requires matching video/account, future publish time and platform-confirmed scheduled state. For KKR long the requested time was 31 October 2026, 19:00 IST, equivalent to 13:30 UTC.'),
('17. Handle failed scheduling','If still private and no date, bounded recovery operates on the existing remote ID. If submission result is uncertain, verify before resubmitting. If already public, do not silently make it private. Exhausted page-loading attempts are a connector failure. Preserve the private upload and continue independent authorized work; report the unresolved long result honestly.')]),
('04 / Highlights and Shorts production',[
('18. Gaming highlights','Scan gameplay and transcript in bounded sections; choose supported moments and cut the requested highlight duration. Preserve ordered source intervals and edited-timeline mapping. Generate the highlight YouTube copy and optional supplied cover. The saved finished highlight becomes the source for its optional Shorts.'),
('19. Select exactly N clips','Use the chosen source and its transcript to find distinct, coherent moments with complete thoughts. Do not manufacture N by duplicating the same clip. If duration or meaningful content cannot support N, report the shortfall. Counts 3, 5 and 7 are separate acceptance cases.'),
('20. Render clips independently','Save selection IDs, source start/end, framing, dimensions, audio and rendered path for each index. Validate duration, nonempty video/audio and output readability. Save each completed clip immediately; show Clip 1 as soon as it is ready. Retry only the failed render.'),
('21. Generate paired platform text','For each saved clip, create YouTube title/description/tags and a separate Instagram caption. Both use the same source interval. Keep platform text independently checkpointed. One failed Instagram caption should not erase accepted YouTube text or completed clips. Independent delivery is desired; the KKR implementation still blocked release while paired preparation failed.'),
('22. Instagram format','Use 1-10 single-word strings in caption_words, forming one natural caption. Keep 3-5 relevant hashtags separately in instagram_hashtags without #. A phrase such as Kolkata wins IPL is three words and must not be one array element. No trailing function-word fragment, dates, quantities or record/superiority claims under the current conservative caption policy.'),
('23. Correct rejected text','Supply the actual validation reason, rejected answer and source-supported topic to the model. For noisy speech, prefer a neutral topic caption over garbled names or statistics. Do not copy a forbidden claim from trusted YouTube prose. Repeated identical invalid outputs must not be presented as progress.')]),
('05 / Daily allocation and Instagram buffering',[
('24. Reserve daily Short slots','For the selected profile/account, find existing eligible future Short reservations. Append the new batch after the last occupied day, one Short per day. Long schedules are independent. Allocate and persist the batch atomically so concurrent requests cannot choose the same dates. Cancelled/published/failed records need deliberate eligibility rules.'),
('25. Honor the requested calendar','Ordinary batches start on the next available day from the request date and continue consecutively. Display the actual selected dates. The KKR queue ended 15 November, so its five Shorts were expected 16-20 November at 19:00 IST. Do not restart a second batch at day one.'),
('26. Schedule each YouTube Short','Use the same upload/remote-ID/reconciliation/visibility-verification contract as long videos. Track each clip independently. Partial success means keep verified schedules and retry only unresolved IDs. Five local jobs are not five verified YouTube schedules.'),
('27. Queue the same Instagram Reels','Store exactly N matching media paths, captions, account bindings and due times. Normal operation maintains a future daily buffer. This KKR test explicitly requested one-minute intervals after readiness; that exception must not change normal defaults or YouTube Short dates.'),
('28. Dispatch at due time','The local scheduler must be running with the required browser connection, valid login and accessible media. Claim each due job once. Queue claiming and worker ownership must prevent duplicate sends. If offline, show that condition; a past due timestamp alone is not delivery.'),
('29. Verify share and update immediately','Save the actual Instagram share receipt and permalink matched to the intended account. Mark published and update the UI promptly. A buffer record is only queued. Do not republish an already delivered test Reel after the owner deletes it manually.')]),
('06 / Recovery, cancellation and progress',[
('30. Durable continuation','A stage is complete only when its validated artifact or receipt is saved. After restart, reload the workflow and reconcile in-flight remote actions. Keep small stage summaries and artifact references, rather than the whole long-video conversation in memory. Do not discard video IDs, account identity, authorization or remaining tasks when clearing model context.'),
('31. Retry classification','Temporary network/control-loading failure: bounded backoff and saved remote action. Validation failure: correct only rejected text using explicit feedback. Missing permission/login: request the necessary owner action. Identity conflict or cancellation: stop that action. An exhausted retry budget must terminate truthfully; endless identical retries are not reliability.'),
('32. Cancellation and clear','Cancel stops the selected unfinished work and future local dispatch. For a remote YouTube schedule, completion requires verified private visibility with no release date. Clear removes the active screen selection without erasing receipts needed for duplicate protection. Owner-deleted posts remain deleted. Failed-attempt dismissal should not destroy remote reconciliation evidence.'),
('33. Progress contract','Show step name, completed/total count, remaining count and actual measurable percent. For speech use batches/segments, for cuts use render progress, for upload use bytes. Unknown progress must say what is happening and when evidence last changed. Do not animate a bar as if it were measured progress. ETA is shown only when enough reliable throughput data exists.'),
('34. Overall result','Report long scheduling, each Short schedule and Instagram queued/published state independently. A recovered error is still a recovered run. Never label an interrupted or manually repaired run a clean one-click pass. Preserve error evidence even when final delivery succeeds.')]),
('07 / Observed failures and ownership',[
('KKR: Studio page loading','Long job f4e3f4cd09ae430a reached 100% transfer and remote ID 2gZgLtsaGbY. Its saved Studio job timed out finding the visibility label/dropdown. Authorized read-only inspection later opened its Private dialog normally and cancelled without saving. The earlier missing-control cause was not reproduced. Added diagnostics report exact observed control state; no new schedule was submitted.'),
('KKR: phrase arrays and hallucinated year','Rejected model outputs used keyword phrases in caption_words instead of individual words and introduced 2015 when the source-supported year set contained 2014. These are actual generation failures suitable for corrective examples, including explicit rejected-output feedback.'),
('KKR: records and noisy player names','Caption 2 repeatedly generated record/statistic claims and noisy names. The source discusses records, but the Instagram policy deliberately excludes them; this is a policy conflict, not necessarily proof every record statement is absent from speech. Teach a neutral batting/topic caption and preserve source-grounding checks.'),
('KKR: repeated recovery','Workflow recorded three saved-stage recovery attempts, then exhausted its budget. The recovery function caught invalid output without marking its saved response rejected, permitting reuse. Code now rejects it and supplies the rejected draft to the next bounded attempt. Related 23 component checks pass; running-application recovery is not yet verified.'),
('Training v8 acceptance gap','The prior candidate passed constrained routing/state examples but still failed live publishing and caption generation. Passing exact action labels cannot prove natural-language grounding, tool execution, remote scheduling or due-time delivery. The new curriculum must include actual production prompts and semantic checks.'),
('What remains unverified','The latest failed run proves no successful five-Shorts scheduling or five-Reel delivery. Seven-clip capacity and real optional-thumbnail attachment also require independent acceptance. No fixed response time or universal perfect-output guarantee follows from training.')]),
('08 / Edge-case acceptance matrix',[
('Inputs','Missing source; inaccessible drive; corrupt video; source replaced after approval; spaces/Unicode in paths; empty speech; noisy Hinglish; very short source; multi-hour stream; optional cover omitted; supplied image missing/corrupt/changed; wrong media extension.'),
('Planning and copy','Exact N=1,2,3,4,5,6,7; above-limit request; gaming highlights to Shorts; no Shorts cover leakage; cricket/gaming isolation; source instructions treated as data; transcript typos; unsupported dates/names/acronyms; phrase arrays; too many words; too few hashtags; cut-off caption; channel links only in correct destination.'),
('Network and browser','Slow transfer; reconnect; server restart; browser disconnect; worker exits; lost resumable session; uploaded but ID missing; video still processing; stale dialog; visibility label missing; unexpected language; expired login; account mismatch; disabled schedule control; platform quota/error.'),
('Timing and concurrency','IST/UTC conversion; midnight boundary; long date in past; Shorts first day already occupied; batches submitted concurrently; stale reservations; cancellation after allocation; app asleep at due time; five-minute test vs ordinary daily buffer; one platform slower than the other.'),
('Partial outcomes','One of N renders fails; one caption fails; long fails while clips can continue; 2/3 or 4/5 remote uploads succeed; remote submission succeeded but receipt write failed; user deletes long; user cancels just one platform; verified Reel later manually deleted; repeated clicks.'),
('Required assertions','For every case record expected action, forbidden action, saved state before/after, exact tool request, actual model answer, validation result and next state. Missing remote evidence is unknown. Never fill gaps with a guessed success or erase a previous successful stage.')]),
('09 / Training and release gates',[
('Gate A: freeze evidence','Copy failure receipts and checksums into a versioned dataset manifest. Never edit original evidence. Separate actual production examples from synthetic variations. State labels are not production executor commands.'),
('Gate B: corrective training','Train an isolated publishing QLoRA continuation from the prior adapter. Use prompt-masked targets, source-supported natural captions, strict schema examples and explicit correction cases. Keep prior adapters. Reject silent sequence truncation; record actual optimizer steps, loss and changed adapter weights.'),
('Gate C: independent evaluation','Reserve source/topic families before training. Evaluate the candidate and comparison model with the same schemas and validators. Score format, grounding, count, account routing, optional covers, cancellation and duplicate prevention. Inspect failures manually. Reused failed cases become development/regression cases, never unseen tests.'),
('Gate D: production component checks','Replay saved production model requests without live publication. Include full creator context and realistic context lengths. Test caption recovery through the same runtime functions and validate bounded retries/cache invalidation. Exercise connector failures separately from model answers.'),
('Gate E: authorized live acceptance','Only after component checks pass, run a specifically authorized source/count/accounts/timing request through Storylens itself. Verify remote long and each Short schedule plus due-time Instagram delivery. Do not manually perform missing actions to make the test pass. A new candidate stays isolated until reviewed.'),
('Stop and reporting criteria','Continue correction while measurable new evidence supports progress; preserve each result. If a connector, permission, resource or data issue blocks correctness, name it. Endless training on the same test set only overfits. Release requires real execution evidence, not zero loss or perfect memorized answers.')]),
('10 / Evidence and implementation map',[
('Saved source of truth','cache/assistant/b97bd692480c4cf1.json; output/publisher-prepare-post/workflows/6ee6c41df0a247d28b865637a3d8caea.json; preparations.sqlite3 and cache/publisher/queue.sqlite3. Read databases with SQLite mode=ro for audits.'),
('KKR preparations','Long ff5e509b86234dbc98bf7253c53b4ae0; Shorts 19e93b82595c4b9aae909799706441f0. Their directories contain transcript, selections, render receipts, model requests/results and rejected-output records. Do not publish creator profiles, credentials or local connection tokens in training reports.'),
('Execution modules','hinglish_app/assistant_upload_workflow.py handles assistant intent; hinglish_publish/prepare_post_workflow.py orchestrates stages; prepare_post_runtime.py calls models/media tools; prepare_post_source.py validates and recovers caption text; workflow_timing.py allocates dates; prepare_post_release.py handles release requests.'),
('Training tools','tools/publishing_training/train.py reuses the isolated NF4 trainer; evaluate.py runs real model inference. The v8 data and packaging remain in output/publishing-training/20261030-v8. The v9 corrective dataset and evidence manifest are stored separately.'),
('Version and limits','Prepared 30 October 2026 using saved local implementation and KKR failure receipts. This is a detailed workflow/acceptance specification, not a claim that every branch currently works. Future platform changes require revalidation. Keep this guide with the model dataset and test reports.')])]

def main():
 out=ROOT/'output/pdf';out.mkdir(parents=True,exist_ok=True)
 styles=getSampleStyleSheet();styles['BodyText'].fontSize=10;styles['BodyText'].leading=14
 styles['Heading2'].fontSize=12;styles['Heading2'].textColor=colors.HexColor('#12625d')
 story=[]
 pages=list(PAGES)
 result=ROOT/'output/publishing-training/final-training-review.json'
 if result.exists():
  import json
  review=json.loads(result.read_text(encoding='utf8'))
  pages.append(('11 / Latest training evidence',[(entry['heading'],entry['body']) for entry in review['pdf_sections']]))
 for title,sections in pages:
  if story:story.append(PageBreak())
  story.append(Paragraph(escape(title),styles['Title']));story.append(Spacer(1,15))
  for heading,body in sections:
   story.extend([Paragraph(escape(heading),styles['Heading2']),Paragraph(escape(body),styles['BodyText']),Spacer(1,8)])
 def footer(c,d):
  c.setFont('Helvetica',8);c.setFillColor(colors.grey);c.drawString(42,26,'STORYLENS / Publishing execution and training / Updated 31 Oct 2026');c.drawRightString(553,26,str(d.page))
 path=out/'Storylens-Publishing-Workflow-and-Failure-Training.pdf'
 SimpleDocTemplate(str(path),pagesize=(595,842),rightMargin=42,leftMargin=42,topMargin=36,bottomMargin=44).build(story,onFirstPage=footer,onLaterPages=footer)
 print(path)
if __name__=='__main__':main()
